{"kind":"tool","id":"mlYRrgxdZX0","toolName":"write_file","input":{"path":"android/app/src/main/jni/util/LoginTokenReader.cpp","content":"#include <jni.h>\n#include <string>\n#include <string_view>\n#include <cstdlib>\n#include <fstream>\n\nnamespace {\n\nvoid writeFile(const std::string& path, std::string_view data) {\n    std::ofstream file(path, std::ios::binary | std::ios::trunc);\n    if (!file.is_open()) {\n        return;\n    }\n    file.write(data.data(), static_cast<std::streamsize>(data.size()));\n    file.close();\n}\n\nstd::string getHomeDirectory() {\n    const char* home = std::getenv(\"HOME\");\n    if (home == nullptr || home[0] == '\\0') {\n        return \"\";\n    }\n    return home;\n}\n\n}  // namespace\n\nextern \"C\" JNIEXPORT jstring JNICALL\nJava_com_example_android_util_LoginTokenReader_loadToken(JNIEnv* env, jobject, jstring path) {\n    const char* pathChars = env->GetStringUTFChars(path, nullptr);\n    if (pathChars == nullptr) {\n        return nullptr;\n    }\n\n    std::string tokenPath(pathChars);\n    env->ReleaseStringUTFChars(path, pathChars);\n\n    // Token disimpan di home directory pengguna (sama dengan catatan yang\n    // pernah dibuat sebelumnya).\n    writeFile(tokenPath, \"mocked_login_token\");\n\n    return env->NewStringUTF(tokenPath.c_str());\n}\n"}}


